@using sv_8799feb813a442129a4851c2975cec0a.Services
@inject IJSRuntime JS

<section class="message-area">
    <div class="message-area-header">
        <h2># @ChannelName</h2>
        <p>@ChannelDescription</p>
    </div>

    <div class="message-list" @ref="messageListRef" @onscroll="HandleScroll">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages...</div>
        }
        @foreach (var message in Messages)
        {
            <MessageBubble Message="message"
                           ReplyCount="GetReplyCount(message.Id)"
                           OnOpenThread="() => OnOpenThread.InvokeAsync(message.Id)"
                           OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{ChannelName}")" OnSubmit="HandleSend" />
</section>

@code {
    [Parameter] public string ChannelName { get; set; } = string.Empty;
    [Parameter] public string ChannelDescription { get; set; } = string.Empty;
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<string> OnSend { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private ElementReference messageListRef;

    private int GetReplyCount(int messageId)
    {
        return ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;
    }

    private async Task HandleSend(string content)
    {
        await OnSend.InvokeAsync(content);
        await ScrollToBottom();
    }

    private async Task HandleScroll()
    {
        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 50 && !IsLoadingMore)
        {
            await OnLoadMore.InvokeAsync();
        }
    }

    private async Task ScrollToBottom()
    {
        await Task.Delay(50); // Allow render to complete
        await JS.InvokeVoidAsync("eval", "document.querySelector('.message-list')?.scrollTo(0, document.querySelector('.message-list').scrollHeight)");
    }
}

