{"file_text": "@page "/chat"
@using sv_8799feb813a442129a4851c2975cec0a.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout @(threadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea ChannelName="@activeChannel?.Name"
                 ChannelDescription="@activeChannel?.Description"
                 Messages="messages"
                 ThreadReplyCounts="threadReplyCounts"
                 IsLoadingMore="isLoadingMore"
                 OnSend="SendMessage"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnLoadMore="LoadMoreMessages" />

    @if (threadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     ThreadMessages="threadMessages"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply"
                     OnReact="HandleReaction" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<Message> threadMessages = [];
    private Dictionary<int, int> threadReplyCounts = [];
    private Message? threadRootMessage;

    private int activeChannelId;
    private Channel? activeChannel;
    private bool threadOpen;
    private bool isLoadingMore;
    private bool allMessagesLoaded;

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        activeChannelId = channelId;
        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = [];
        threadReplyCounts = [];
        allMessagesLoaded = false;
        CloseThreadInternal();

        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channelId);
        UpdateThreadReplyCounts();

        // Update unread count locally
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task SendMessage(string content)
    {
        var newMessage = await ChatService.SendMessageAsync(activeChannelId, content, null);
        messages.Add(newMessage);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadMessages = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThreadInternal()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadMessages = [];
    }

    private Task CloseThread()
    {
        CloseThreadInternal();
        return Task.CompletedTask;
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootMessage.Id);
        threadMessages.Add(reply);

        // Update reply count
        if (threadReplyCounts.ContainsKey(threadRootMessage.Id))
            threadReplyCounts[threadRootMessage.Id]++;
        else
            threadReplyCounts[threadRootMessage.Id] = 1;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update the local message
        UpdateReactionLocally(messages, args.MessageId, args.Emoji);
        UpdateReactionLocally(threadMessages, args.MessageId, args.Emoji);
    }

    private static void UpdateReactionLocally(List<Message> messageList, int messageId, string emoji)
    {
        var idx = messageList.FindIndex(m => m.Id == messageId);
        if (idx < 0) return;

        var msg = messageList[idx];
        var existingReaction = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
        if (existingReaction is not null)
        {
            if (!existingReaction.Users.Contains("You"))
                existingReaction.Users.Add("You");
        }
        else
        {
            msg.Reactions.Add(new Reaction(emoji, ["You"]));
        }
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore || allMessagesLoaded) return;

        isLoadingMore = true;
        var olderMessages = await ChatService.GetMessagesAsync(activeChannelId, messages.Count, PageSize);

        if (olderMessages.Count < PageSize)
            allMessagesLoaded = true;

        messages.InsertRange(0, olderMessages);
        UpdateThreadReplyCounts();
        isLoadingMore = false;
    }

    private void UpdateThreadReplyCounts()
    {
        // Messages with ReplyToId indicate they are replies; count them per root
        var replyCounts = messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());

        foreach (var (rootId, count) in replyCounts)
        {
            threadReplyCounts[rootId] = count;
        }
    }
}
